// ---------- Auto backup (controller-wide) ----------

const autoBackupPath = "/autoBackup/autoBackupTask"

// AutoBackup reads the controller's scheduled-backup task.
func (c *Client) AutoBackup(ctx context.Context) (map[string]any, error) {
	var out map[string]any
	return out, c.Do(ctx, http.MethodGet, autoBackupPath, nil, &out)
}

// PutAutoBackup replaces the scheduled-backup task. The controller ignores
// the schedule fields while the task is disabled.
