// ---------- Controller admin accounts ----------

// AdminUser is a controller account.
type AdminUser struct {
	ID       string         `json:"id,omitempty"`
	Name     string         `json:"name"`
	Type     int            `json:"type"` // 0 local, 1 cloud
	RoleID   string         `json:"roleId"`
	RoleName string         `json:"roleName,omitempty"`
	Email    string         `json:"email,omitempty"`
	Alert    bool           `json:"alert"`
	Owner    bool           `json:"owner,omitempty"`
	Raw      map[string]any `json:"-"`
}

// AdminUsers lists controller accounts.
func (c *Client) AdminUsers(ctx context.Context) ([]AdminUser, error) {
	raws, err := listAll[map[string]any](ctx, c, "/account/users")
	if err != nil {
		return nil, err
	}
	out := make([]AdminUser, 0, len(raws))
	for _, r := range raws {
		var u AdminUser
		if err := remarshal(r, &u); err != nil {
			return nil, err
		}
		u.Raw = r
		out = append(out, u)
	}
	return out, nil
}

// AdminUser reads one account by ID.
func (c *Client) AdminUser(ctx context.Context, id string) (*AdminUser, error) {
	all, err := c.AdminUsers(ctx)
	if err != nil {
		return nil, err
	}
	for i := range all {
		if all[i].ID == id {
			return &all[i], nil
		}
	}
	return nil, &NotFoundError{What: fmt.Sprintf("admin user %q", id)}
}

// AdminUserBody builds the create/edit body for a local account with access
// to all sites (siteIDs empty) or the listed sites. password may be empty on
// edit to keep the current password.
func AdminUserBody(name, roleID, password string, siteIDs []string, alert bool) map[string]any {
	priv := map[string]any{"all": len(siteIDs) == 0, "sites": siteIDs}
	if siteIDs == nil {
		priv["sites"] = []string{}
	}
	b := map[string]any{"name": name, "type": 0, "roleId": roleID, "privilege": priv, "alert": alert}
	if password != "" {
		b["password"] = password
	}
	return b
}

// CreateAdminUser creates a local account and returns its ID.
func (c *Client) CreateAdminUser(ctx context.Context, body map[string]any) (string, error) {
	var res struct {
		UserID string `json:"userId"`
	}
	if err := c.Do(ctx, http.MethodPost, "/account/users", body, &res); err != nil {
		return "", err
	}
	return res.UserID, nil
}

// UpdateAdminUser edits an account (PATCH with the full body).
func (c *Client) UpdateAdminUser(ctx context.Context, id string, body map[string]any) error {
	return c.Do(ctx, http.MethodPatch, "/account/users/"+url.PathEscape(id), body, nil)
}

// DeleteAdminUser deletes an account. Without forceDelete the controller
// answers "General error".
func (c *Client) DeleteAdminUser(ctx context.Context, id string) error {
	return c.Do(ctx, http.MethodDelete, "/users/"+url.PathEscape(id), map[string]any{"forceDelete": true}, nil)
}

// ---------- Adopted device settings ----------

func devicePath(siteID, devType, mac string) (string, error) {
	seg := map[string]string{"ap": "eaps", "switch": "switches", "gateway": "gateways"}[devType]
	if seg == "" {
		return "", fmt.Errorf("unsupported device type %q", devType)
	}
	return sitePath(siteID, "/"+seg+"/"+url.PathEscape(NormalizeMAC(mac))), nil
}

// DeviceDetail reads an adopted device's settings. devType is ap, switch or
// gateway (as reported by the device list).
func (c *Client) DeviceDetail(ctx context.Context, siteID, devType, mac string) (map[string]any, error) {
	p, err := devicePath(siteID, devType, mac)
	if err != nil {
		return nil, err
	}
	var out map[string]any
	return out, c.Do(ctx, http.MethodGet, p, nil, &out)
}

// PatchDevice changes device settings. Partial bodies are accepted, e.g.
// {"name": "AP-1"} or {"ledSetting": 0}. The response (which echoes
// secrets such as SSID keys) is discarded.
func (c *Client) PatchDevice(ctx context.Context, siteID, devType, mac string, body map[string]any) error {
	p, err := devicePath(siteID, devType, mac)
	if err != nil {
		return err
	}
	return c.Do(ctx, http.MethodPatch, p, body, nil)
}

// ---------- Reboot schedules ----------

const rebootSchedulePath = "/setting/service/rebootSchedules"

// RebootSchedule reboots devices on a schedule. Occurrence timingType: 1
// daily, 2 weekly (dayOfWeek 0 Sunday), 3 monthly (dayOfMonth).
type RebootSchedule struct {
	ID         string         `json:"id,omitempty"`
	Name       string         `json:"name"`
	Status     bool           `json:"status"`
	DeviceMACs []string       `json:"deviceMacs"`
	Occurrence map[string]any `json:"occurrence"`
}

// RebootSchedule reads one schedule.
func (c *Client) RebootSchedule(ctx context.Context, siteID, id string) (*RebootSchedule, error) {
	raw, err := findRaw(ctx, c, sitePath(siteID, rebootSchedulePath), "id", id, "reboot schedule")
	if err != nil {
		return nil, err
	}
	var r RebootSchedule
	return &r, remarshal(raw, &r)
}

// CreateRebootSchedule creates a schedule and returns its ID (found by name;
// the create response has no ID).
func (c *Client) CreateRebootSchedule(ctx context.Context, siteID string, r RebootSchedule) (string, error) {
	r.ID = ""
	return createAndFind(ctx, c, sitePath(siteID, rebootSchedulePath), "id", r.Name, r)
}

// UpdateRebootSchedule replaces a schedule (PUT).
func (c *Client) UpdateRebootSchedule(ctx context.Context, siteID, id string, r RebootSchedule) error {
	r.ID = ""
	return c.Do(ctx, http.MethodPut, sitePath(siteID, rebootSchedulePath+"/"+url.PathEscape(id)), r, nil)
}

// DeleteRebootSchedule deletes a schedule.
func (c *Client) DeleteRebootSchedule(ctx context.Context, siteID, id string) error {
	return c.Do(ctx, http.MethodDelete, sitePath(siteID, rebootSchedulePath+"/"+url.PathEscape(id)), nil, nil)
}
